-- =============================================================================================
-- Hand-written below this line: incident checks, at most one place (active, of the property),
-- numbering per property; what was reported never changes; OPEN -> RESPONDING -> RESOLVED ->
-- CLOSED (also OPEN -> RESOLVED, and RESOLVED -> RESPONDING to reopen with a note), resolving
-- needs an outcome, closing needs every follow-up action done, times set by the database; every
-- status change logged by the database; the timeline is append-only; actions done once and not
-- added to closed incidents. See docs/architecture/DATA_MODEL.md section 12 (Incidents).
-- =============================================================================================

ALTER TABLE "incidents" ADD CONSTRAINT "incidents_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 160
         AND "description" = btrim("description") AND length("description") BETWEEN 1 AND 4000
         AND ("location_detail" IS NULL OR ("location_detail" = btrim("location_detail") AND length("location_detail") BETWEEN 1 AND 200))
         AND ("outcome" IS NULL OR ("outcome" = btrim("outcome") AND length("outcome") BETWEEN 1 AND 4000)));
ALTER TABLE "incidents" ADD CONSTRAINT "incidents_place"
  CHECK (num_nonnulls("unit_id", "common_area_id") <= 1);
ALTER TABLE "incidents" ADD CONSTRAINT "incidents_number_set"
  CHECK ("incident_number" IS NOT NULL AND "incident_number" >= 1);
ALTER TABLE "incidents" ADD CONSTRAINT "incidents_dates"
  CHECK (("status" IN ('RESOLVED', 'CLOSED')) = ("resolved_at" IS NOT NULL)
         AND ("status" IN ('RESOLVED', 'CLOSED')) = ("outcome" IS NOT NULL)
         AND ("status" = 'CLOSED') = ("closed_at" IS NOT NULL));

CREATE FUNCTION app_incident_log(i "incidents", from_status "IncidentStatus", note text) RETURNS void
  LANGUAGE sql
  AS $$
    INSERT INTO "incident_updates" ("id", "organisation_id", "property_id", "incident_id", "kind", "from_status",
                                    "to_status", "body", "actor_user_id")
    VALUES (gen_random_uuid(), i."organisation_id", i."property_id", i."id", 'STATUS_CHANGED', from_status,
            i."status", note, app_current_user_id())
  $$;

CREATE FUNCTION app_incident_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  transition text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'OPEN' THEN
      RAISE EXCEPTION 'incidents start open' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."occurred_at" > now() + interval '5 minutes' THEN
      RAISE EXCEPTION 'an incident cannot happen in the future' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."unit_id" IS NOT NULL OR NEW."common_area_id" IS NOT NULL THEN
      PERFORM app_maintenance_location_active(NEW."property_id", NEW."unit_id", NEW."common_area_id");
    END IF;
    NEW."created_at" := now();
    NEW."outcome" := NULL;
    NEW."resolved_at" := NULL;
    NEW."closed_at" := NULL;
    PERFORM pg_advisory_xact_lock(hashtextextended('veyra.incidents:' || NEW."property_id"::text, 0));
    SELECT coalesce(max("incident_number"), 0) + 1 INTO NEW."incident_number"
      FROM "incidents" WHERE "property_id" = NEW."property_id";
    RETURN NEW;
  END IF;
  IF OLD."status" = 'CLOSED' THEN
    RAISE EXCEPTION 'incident % is closed and no longer changes', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."incident_number", NEW."title", NEW."description",
      NEW."occurred_at", NEW."unit_id", NEW."common_area_id", NEW."location_detail", NEW."reported_by_user_id",
      NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."incident_number", OLD."title", OLD."description",
      OLD."occurred_at", OLD."unit_id", OLD."common_area_id", OLD."location_detail", OLD."reported_by_user_id",
      OLD."created_at") THEN
    RAISE EXCEPTION 'what was reported in incident % never changes; add a note', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  NEW."resolved_at" := OLD."resolved_at";
  NEW."closed_at" := OLD."closed_at";
  IF NEW."status" = OLD."status" THEN
    NEW."outcome" := OLD."outcome";
    RETURN NEW;
  END IF;
  transition := OLD."status" || '>' || NEW."status";
  IF transition NOT IN ('OPEN>RESPONDING', 'OPEN>RESOLVED', 'RESPONDING>RESOLVED', 'RESOLVED>RESPONDING', 'RESOLVED>CLOSED') THEN
    RAISE EXCEPTION 'an incident cannot go from % to %', lower(OLD."status"::text), lower(NEW."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = 'RESOLVED' THEN
    IF NEW."outcome" IS NULL THEN
      RAISE EXCEPTION 'say how the incident ended to resolve it' USING ERRCODE = 'check_violation';
    END IF;
    NEW."resolved_at" := now();
  ELSIF transition = 'RESOLVED>RESPONDING' THEN
    NEW."outcome" := NULL;
    NEW."resolved_at" := NULL;
  ELSIF NEW."status" = 'CLOSED' THEN
    NEW."outcome" := OLD."outcome";
    IF EXISTS (SELECT 1 FROM "incident_actions" WHERE "incident_id" = OLD."id" AND "done_at" IS NULL) THEN
      RAISE EXCEPTION 'finish the follow-up actions before closing the incident' USING ERRCODE = 'check_violation';
    END IF;
    NEW."closed_at" := now();
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "incidents_guard"
  BEFORE INSERT OR UPDATE ON "incidents"
  FOR EACH ROW EXECUTE FUNCTION app_incident_guard();

CREATE FUNCTION app_incident_status_log() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM app_incident_log(NEW, NULL, NULL);
  ELSIF NEW."status" IS DISTINCT FROM OLD."status" THEN
    PERFORM app_incident_log(NEW, OLD."status", NEW."outcome");
  END IF;
  RETURN NULL;
END
$$;

CREATE TRIGGER "incidents_log"
  AFTER INSERT OR UPDATE ON "incidents"
  FOR EACH ROW EXECUTE FUNCTION app_incident_status_log();

ALTER TABLE "incident_updates" ADD CONSTRAINT "incident_updates_shape"
  CHECK (("kind" = 'NOTE') = ("to_status" IS NULL)
         AND ("kind" <> 'NOTE' OR ("body" IS NOT NULL AND "actor_user_id" IS NOT NULL))
         AND ("body" IS NULL OR ("body" = btrim("body") AND length("body") BETWEEN 1 AND 4000)));

CREATE FUNCTION app_incident_update_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."kind" <> 'NOTE' AND pg_trigger_depth() < 2 THEN
    RAISE EXCEPTION 'status changes are logged by the database; add a note instead' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW."kind" = 'NOTE' AND EXISTS (SELECT 1 FROM "incidents" WHERE "id" = NEW."incident_id" AND "status" = 'CLOSED') THEN
    RAISE EXCEPTION 'the incident is closed' USING ERRCODE = 'check_violation';
  END IF;
  NEW."created_at" := clock_timestamp();
  RETURN NEW;
END
$$;

CREATE TRIGGER "incident_updates_insert"
  BEFORE INSERT ON "incident_updates"
  FOR EACH ROW EXECUTE FUNCTION app_incident_update_insert();

CREATE FUNCTION app_incident_update_append_only() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  RAISE EXCEPTION 'the incident timeline is append-only' USING ERRCODE = 'insufficient_privilege';
END
$$;

CREATE TRIGGER "incident_updates_append_only"
  BEFORE UPDATE OR DELETE ON "incident_updates"
  FOR EACH ROW EXECUTE FUNCTION app_incident_update_append_only();
CREATE TRIGGER "incident_updates_no_truncate"
  BEFORE TRUNCATE ON "incident_updates"
  FOR EACH STATEMENT EXECUTE FUNCTION app_incident_update_append_only();

ALTER TABLE "incident_actions" ADD CONSTRAINT "incident_actions_text"
  CHECK ("description" = btrim("description") AND length("description") BETWEEN 1 AND 500
         AND ("done_at" IS NULL) = ("done_by_user_id" IS NULL));

CREATE FUNCTION app_incident_action_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF EXISTS (SELECT 1 FROM "incidents" WHERE "id" = NEW."incident_id" AND "status" = 'CLOSED') THEN
      RAISE EXCEPTION 'the incident is closed' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    NEW."done_at" := NULL;
    NEW."done_by_user_id" := NULL;
    RETURN NEW;
  END IF;
  IF OLD."done_at" IS NOT NULL
     OR (NEW."organisation_id", NEW."property_id", NEW."incident_id", NEW."description", NEW."created_at")
        IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."incident_id", OLD."description", OLD."created_at") THEN
    RAISE EXCEPTION 'action % is done once; its description never changes', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."done_at" IS NOT NULL THEN
    IF app_current_user_id() IS NULL THEN
      RAISE EXCEPTION 'an action is done by a person' USING ERRCODE = 'check_violation';
    END IF;
    NEW."done_at" := now();
    NEW."done_by_user_id" := app_current_user_id();
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "incident_actions_guard"
  BEFORE INSERT OR UPDATE ON "incident_actions"
  FOR EACH ROW EXECUTE FUNCTION app_incident_action_guard();

ALTER TABLE "escalation_contacts" ADD CONSTRAINT "escalation_contacts_text"
  CHECK ("name" = btrim("name") AND length("name") BETWEEN 1 AND 120
         AND "role" = btrim("role") AND length("role") BETWEEN 1 AND 120
         AND "phone" = btrim("phone") AND length("phone") BETWEEN 3 AND 40
         AND ("email" IS NULL OR ("email" = lower(btrim("email")) AND "email" ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'))
         AND "position" BETWEEN 0 AND 1000);

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['incidents', 'incident_updates', 'incident_actions', 'escalation_contacts'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['incidents', 'incident_actions', 'escalation_contacts'] LOOP
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "incidents", "incident_updates", "incident_actions", "escalation_contacts" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "incidents", "incident_actions", "escalation_contacts" TO veyra_app;
GRANT SELECT, INSERT ON "incident_updates" TO veyra_app;
GRANT USAGE ON SEQUENCE "incident_updates_sequence_seq" TO veyra_app;
